47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        // Validate & normalize the optional email; reject the create when it is present but invalid.
127	        if (!normalizeEmail(ownerFieldsDto)) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        // Reject the create when another owner already uses this email (compared case-insensitively
131	        // by lower-cased email). The DTO email is already normalized to its lower-cased form here.
132	        String normalizedEmail = ownerFieldsDto.getEmail();
133	        if (normalizedEmail != null) {
134	            boolean emailInUse = this.clinicService.findAllOwners().stream()
135	                .map(Owner::getEmail)
136	                .filter(existing -> existing != null)
137	                .map(existing -> existing.toLowerCase(Locale.ROOT))
138	                .anyMatch(normalizedEmail::equals);
139	            if (emailInUse) {
140	                return new ResponseEntity<>(HttpStatus.CONFLICT);
141	            }
142	        }
143	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
144	        // abbreviations) and store the normalized form back on the DTO so it is what gets
145	        // persisted and compared. Reject the create when the address is blank once normalized.
146	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
147	        if (canonicalAddress.isBlank()) {
148	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
149	        }
150	        ownerFieldsDto.setAddress(canonicalAddress);
151	        // Reject the create when the owner's city is already at capacity, i.e. it already
152	        // contains 50 or more owners (compared case-insensitively).
153	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
157	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
158	        if (normalizedTelephone == null) {
159	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
160	        }
161	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
162	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
163	            .map(Owner::getTelephone)
164	            .map(OwnerRestControllerV1::toE164)
165	            .filter(existing -> existing != null)
166	            .anyMatch(normalizedTelephone::equals);
167	        if (telephoneInUse) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        // Reject the create when another owner already shares this owner's last name and address
171	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
172	        // sharing a household.
173	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
174	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
175	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
176	            boolean householdInUse = this.clinicService.findAllOwners().stream()
177	                .anyMatch(existing ->
178	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
179	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
180	            if (householdInUse) {
181	                return new ResponseEntity<>(HttpStatus.CONFLICT);
182	            }
183	        }
184	        // Determine the effective registration date — the value supplied on the request, or the
185	        // server's current date when none was supplied — and roll it forward to the next business
186	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
187	        // registration date (membership-number year segment, per-day create-limit) uses this
188	        // adjusted date.
189	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
190	        if (registrationDate == null) {
191	            registrationDate = LocalDate.now();
192	        }
193	        registrationDate = toBusinessDay(registrationDate);
194	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
195	        // owners have already been registered on this (adjusted) business day.
196	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
197	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
198	        }
199	        ownerFieldsDto.setTelephone(normalizedTelephone);
200	        HttpHeaders headers = new HttpHeaders();
201	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
202	        owner.setRegistrationDate(registrationDate);
203	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
204	        // letters of the city, the upper-cased first three letters of the last name, and a
205	        // per-city 4-digit sequence one greater than the number of owners already in that city.
206	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
207	        // Record how many existing owners already share this owner's first and last name
208	        // (compared case-insensitively) at the moment before this owner is created.
209	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
210	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
211	        // registered on this (adjusted) business day before this owner is created.
212	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
213	        // Record the size of this owner's household after this create: the number of existing
214	        // owners sharing the same household (matching last name and address) plus this owner.
215	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
216	        this.clinicService.saveOwner(owner);
217	        // Emit an audit line recording the new owner's id, customer code, registration date
218	        // and membership level.
219	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
220	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
221	            ownerMapper.membershipLevel(owner));
222	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
226	    }
227	
228	    /**
229	     * Validate and normalize the optional owner email in place.
230	     *
231	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
232	     * When present it must be a syntactically valid address; a valid address is
233	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
234	     * present but syntactically invalid, so the caller can reject with 400.
235	     */
236	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
237	        String email = ownerFieldsDto.getEmail();
238	        if (email == null || email.isBlank()) {
239	            ownerFieldsDto.setEmail(null);
240	            return true;
241	        }
242	        String normalized = email.trim().toLowerCase(Locale.ROOT);
243	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
244	            return false;
245	        }
246	        ownerFieldsDto.setEmail(normalized);
247	        return true;
248	    }
249	
250	    /**
251	     * Normalize an owner address: trim, collapse each run of whitespace to a single
252	     * space, upper-case, and expand common street-type abbreviations
253	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
254	     * A {@code null} value normalizes to the empty string.
255	     */
256	    private static String normalizeAddress(String value) {
257	        if (value == null) {
258	            return "";
259	        }
260	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
261	        if (collapsed.isEmpty()) {
262	            return "";
263	        }
264	        String[] tokens = collapsed.split(" ");
265	        StringBuilder sb = new StringBuilder(collapsed.length());
266	        for (int i = 0; i < tokens.length; i++) {
267	            if (i > 0) {
268	                sb.append(' ');
269	            }
270	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
271	        }
272	        return sb.toString();
273	    }
274	
275	    /**
276	     * Normalize an owner household field (last name or address) for duplicate detection:
277	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
278	     * A {@code null} value normalizes to the empty string.
279	     */
280	    private static String normalizeHouseholdKey(String value) {
281	        if (value == null) {
282	            return "";
283	        }
284	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
285	    }
286	
287	    /**
288	     * Normalize a telephone number to E.164 form.
289	     *
290	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
291	     * explicit leading {@code '+'} and country code it is kept; otherwise the
292	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
293	     * dropped from the national digits. The result must contain 8 to 15 digits
294	     * after the {@code '+'}.
295	     *
296	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
297	     *         the input is absent or cannot form a valid E.164 number.
298	     */
299	    private static String toE164(String raw) {
300	        if (raw == null) {
301	            return null;
302	        }
303	        String trimmed = raw.trim();
304	        boolean hasCountryCode = trimmed.startsWith("+");
305	        // Strip spaces, dashes and brackets.
306	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
307	        String digits;
308	        if (hasCountryCode) {
309	            // Keep the explicit country code; drop the leading '+' for validation.
310	            digits = stripped.substring(1);
311	        } else {
312	            // No country code: assume '+61' and drop a single leading '0'.
313	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
314	            digits = "61" + national;
315	        }
316	        if (!digits.matches("\\d{8,15}")) {
317	            return null;
318	        }
319	        return "+" + digits;
320	    }
321	
322	    /**
323	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
324	     *
325	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
326	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
327	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
328	     * equal to one more than the number of owners already in that city
329	     * (e.g. {@code 'SYD-SMI-0007'}).
330	     */
331	    /**
332	     * Count the existing owners whose first and last name match the given names,
333	     * compared case-insensitively. Used to record an owner's namesake count at the
334	     * moment before it is created.
335	     */
336	    private int countNamesakes(String firstName, String lastName) {
337	        return (int) this.clinicService.findAllOwners().stream()
338	            .filter(existing -> existing.getFirstName() != null
339	                && existing.getFirstName().equalsIgnoreCase(firstName)
340	                && existing.getLastName() != null
341	                && existing.getLastName().equalsIgnoreCase(lastName))
342	            .count();
343	    }
344	
345	    /**
346	     * Count the existing owners in the same household as the given last name and address
347	     * (compared after household-key normalization). Used, together with the owner being
348	     * created, to derive the household size recorded on the owner.
349	     */
350	    private int countHouseholdMembers(String lastName, String address) {
351	        String normalizedLastName = normalizeHouseholdKey(lastName);
352	        String normalizedAddress = normalizeHouseholdKey(address);
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing ->
355	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
356	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
357	            .count();
358	    }
359	
360	    private String nextCustomerCode(String city, String lastName) {
361	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
362	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
363	        int sequence = countOwnersInCity(city) + 1;
364	        return String.format("%s-%s-%04d", city3, last3, sequence);
365	    }
366	
367	    /**
368	     * Count the existing owners located in the given city, compared case-insensitively.
369	     * Used to derive the per-city 4-digit sequence in the customer code.
370	     */
371	    private int countOwnersInCity(String city) {
372	        return (int) this.clinicService.findAllOwners().stream()
373	            .filter(existing -> existing.getCity() != null
374	                && existing.getCity().equalsIgnoreCase(city))
375	            .count();
376	    }
377	
378	    /**
379	     * Count the existing owners whose registration date is the given (adjusted business) date.
380	     * Used to enforce the per-day sign-up limit.
381	     */
382	    private int countOwnersRegisteredOn(LocalDate date) {
383	        return (int) this.clinicService.findAllOwners().stream()
384	            .filter(existing -> date.equals(existing.getRegistrationDate()))
385	            .count();
386	    }
387	
388	    /**
389	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
390	     * the following Monday; a weekday is returned unchanged.
391	     */
392	    private static LocalDate toBusinessDay(LocalDate date) {
393	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
394	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
395	            date = date.plusDays(1);
396	        }
397	        return date;
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
403	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
404	        if (currentOwner == null) {
405	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
406	        }
407	        if (!normalizeEmail(ownerFieldsDto)) {
408	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
409	        }
410	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
411	        if (normalizedTelephone == null) {
412	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
413	        }
414	        currentOwner.setAddress(ownerFieldsDto.getAddress());
415	        currentOwner.setCity(ownerFieldsDto.getCity());
416	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
417	        currentOwner.setLastName(ownerFieldsDto.getLastName());
418	        currentOwner.setTelephone(normalizedTelephone);
419	        currentOwner.setEmail(ownerFieldsDto.getEmail());
420	        this.clinicService.saveOwner(currentOwner);
421	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Transactional
426	    @Override
427	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
428	        Owner owner = this.clinicService.findOwnerById(ownerId);
429	        if (owner == null) {
430	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
431	        }
432	        this.clinicService.deleteOwner(owner);
433	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
434	    }
435	
436	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
437	    @Override
438	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
439	        Owner owner = this.clinicService.findOwnerById(ownerId);
440	        if (owner == null) {
441	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
442	        }
443	        HttpHeaders headers = new HttpHeaders();
444	        Pet pet = petMapper.toPet(petFieldsDto);
445	        owner.setId(ownerId);
446	        pet.setOwner(owner);
447	        pet.getType().setName(null);
448	        this.clinicService.savePet(pet);
449	        PetDto petDto = petMapper.toPetDto(pet);
450	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
451	            .buildAndExpand(pet.getId()).toUri());
452	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
453	    }
454	
455	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
456	    @Override
457	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
458	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
459	        if (currentOwner != null) {
460	            Pet currentPet = this.clinicService.findPetById(petId);
461	            if (currentPet != null) {
462	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
463	                currentPet.setName(petFieldsDto.getName());
464	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
465	                this.clinicService.savePet(currentPet);
466	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
467	            }
468	        }
469	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
